// Shared executable protocol core, compiled by Cargo and checked by Verus.
use vstd::prelude::*;

verus! {
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct State {
    pub term: u64,
    pub role: Role,
    pub voted_for: Option<usize>,
    pub me: usize,
    pub members: usize,
    pub last_index: u64,
    pub last_term: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Role { Follower, Candidate, Leader }

#[derive(Debug, Clone, Copy)]
#[cfg_attr(not(verus_keep_ghost), derive(serde::Serialize, serde::Deserialize))]
pub struct VoteRequest {
    pub term: u64,
    pub candidate: usize,
    pub last_index: u64,
    pub last_term: u64,
}

#[derive(Debug, Clone, Copy)]
#[cfg_attr(not(verus_keep_ghost), derive(serde::Serialize, serde::Deserialize))]
pub struct VoteReply { pub term: u64, pub granted: bool }

pub open spec fn well_formed(s: State) -> bool {
    s.members > 0 && s.me < s.members
    && (match s.voted_for { Some(n) => n < s.members, None => true })
    && s.last_term <= s.term
}

pub open spec fn initial(s: State, me: usize, members: usize) -> bool {
    well_formed(s) && s.me == me && s.members == members
    && s.term == 0 && s.role == Role::Follower && s.voted_for == None::<usize>
    && s.last_index == 0 && s.last_term == 0
}

pub open spec fn up_to_date(s: State, q: VoteRequest) -> bool {
    q.last_term > s.last_term || (q.last_term == s.last_term && q.last_index >= s.last_index)
}

// Exact local input/state/output relation. It makes no durability assumption.
pub open spec fn vote_step(s: State, q: VoteRequest, t: State, r: VoteReply) -> bool {
    let valid = q.candidate < s.members && q.last_term <= q.term;
    let higher = valid && q.term > s.term;
    let granted = valid && q.term >= s.term && up_to_date(s, q)
        && (higher || s.voted_for == None::<usize> || s.voted_for == Some(q.candidate));
    t.me == s.me && t.members == s.members
    && t.last_index == s.last_index && t.last_term == s.last_term
    && t.term == (if higher { q.term } else { s.term })
    && t.role == (if higher { Role::Follower } else { s.role })
    && t.voted_for == (if granted { Some(q.candidate) } else if higher { None } else { s.voted_for })
    && r.term == t.term && r.granted == granted
}

impl State {
    pub fn new(me: usize, members: usize) -> (result: Option<Self>)
        ensures
            result.is_some() == (members > 0 && me < members),
            result.is_some() ==> initial(result.unwrap(), me, members),
    {
        if members == 0 || me >= members { return None; }
        Some(Self { term: 0, role: Role::Follower, voted_for: None,
            me, members, last_index: 0, last_term: 0 })
    }

    // Recovery validates deployment identity and vote range at the real boundary.
    // Historical durability is a separate obligation of the storage caller.
    pub fn restore_vote(me: usize, members: usize, term: u64, voted_for: Option<usize>)
        -> (result: Option<Self>)
        ensures result.is_some() == (members > 0 && me < members
            && (match voted_for { Some(n) => n < members, None => true })),
            result.is_some() ==> well_formed(result.unwrap())
                && result.unwrap().me == me && result.unwrap().members == members
                && result.unwrap().term == term && result.unwrap().voted_for == voted_for
                && result.unwrap().role == Role::Follower
                && result.unwrap().last_index == 0 && result.unwrap().last_term == 0,
    {
        if members == 0 || me >= members { return None; }
        if let Some(n) = voted_for { if n >= members { return None; } }
        Some(Self { term, role: Role::Follower, voted_for, me, members,
            last_index: 0, last_term: 0 })
    }

    pub fn is_leader(&self) -> (result: bool)
        ensures result == (self.role is Leader),
    { matches!(self.role, Role::Leader) }

    pub fn election_request(&self) -> (r: Option<VoteRequest>)
        ensures r.is_some() == (self.term < u64::MAX),
            r.is_some() ==> r.unwrap().term == self.term + 1
                && r.unwrap().candidate == self.me
                && r.unwrap().last_index == self.last_index && r.unwrap().last_term == self.last_term,
    {
        if self.term == u64::MAX { return None; }
        Some(VoteRequest { term: self.term + 1, candidate: self.me,
            last_index: self.last_index, last_term: self.last_term })
    }
    pub fn campaign(&mut self, term: u64) -> (r: bool)
        requires well_formed(*old(self)),
        ensures well_formed(*self),
            r == (old(self).term == term && old(self).voted_for == Some(old(self).me)),
            self.term == old(self).term, self.voted_for == old(self).voted_for,
            self.me == old(self).me, self.members == old(self).members,
            self.last_index == old(self).last_index, self.last_term == old(self).last_term,
            self.role == (if r { Role::Candidate } else { old(self).role }),
    {
        let valid = self.term == term && self.voted_for == Some(self.me);
        if valid { self.role = Role::Candidate; }
        valid
    }

    pub fn request_vote(&mut self, q: VoteRequest) -> (reply: VoteReply)
        requires well_formed(*old(self)),
        ensures well_formed(*self), vote_step(*old(self), q, *self, reply),
            self.term >= old(self).term,
            old(self).voted_for.is_some() && self.term == old(self).term
                ==> self.voted_for == old(self).voted_for,
    {
        if q.candidate >= self.members || q.last_term > q.term {
            return VoteReply { term: self.term, granted: false };
        }
        if q.term > self.term {
            self.term = q.term;
            self.role = Role::Follower;
            self.voted_for = None;
        }
        let fresh = q.last_term > self.last_term
            || (q.last_term == self.last_term && q.last_index >= self.last_index);
        let available = match self.voted_for {
            None => true,
            Some(candidate) => candidate == q.candidate,
        };
        let granted = q.term == self.term && fresh && available;
        if granted { self.voted_for = Some(q.candidate); }
        VoteReply { term: self.term, granted }
    }
}

}
//! Verified request/storage/reply phases used by the asynchronous Raft host.
use super::state::{self, State, VoteRequest, VoteReply};
use vstd::prelude::*;

verus! {
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(not(verus_keep_ghost), derive(serde::Serialize, serde::Deserialize))]
pub struct VoteImage {
    pub version: u64,
    pub term: u64,
    pub voted_for: Option<usize>,
    pub me: usize,
    pub members: usize,
}

// Only begin_vote constructs this operation. The host borrows its image while
// writing, then returns the owned operation after successful I/O completion.
pub struct WriteVote { id: u64, image: VoteImage }

#[derive(Clone, Copy)]
struct PendingVote {
    id: u64,
    image: VoteImage,
    request: VoteRequest,
    reply: VoteReply,
    before: Ghost<State>,
}

pub struct Machine {
    state: State,
    serial: u64,
    pending: Option<PendingVote>,
}

pub open spec fn image(s: State) -> VoteImage {
    VoteImage { version: 1, term: s.term, voted_for: s.voted_for, me: s.me, members: s.members }
}

// Observable local operation state, including the pending request and exact reply.
pub struct OperationView {
    pub state: State,
    pub serial: u64,
    pub pending: Option<(u64, VoteImage, VoteRequest, VoteReply, State)>,
}

pub open spec fn view_invariant(v: OperationView) -> bool {
    state::well_formed(v.state) && v.state.last_index == 0 && v.state.last_term == 0
    && match v.pending {
        None => true,
        Some(p) => p.0 == v.serial && p.1 == image(v.state)
            && state::well_formed(p.4) && state::vote_step(p.4, p.2, v.state, p.3),
    }
}

pub open spec fn initial_view(v: OperationView, me: usize, members: usize) -> bool {
    state::initial(v.state, me, members) && v.serial == 0 && v.pending.is_none()
}

pub open spec fn begin_step(s: OperationView, q: VoteRequest, t: OperationView,
    output: Option<(u64, VoteImage)>) -> bool {
    if s.pending.is_some() || s.serial == u64::MAX {
        t == s && output.is_none()
    } else {
        t.serial == s.serial + 1 && t.pending.is_some()
        && t.pending.unwrap().0 == t.serial && t.pending.unwrap().1 == image(t.state)
        && t.pending.unwrap().2 == q && t.pending.unwrap().4 == s.state
        && state::vote_step(s.state, q, t.state, t.pending.unwrap().3)
        && output == Some((t.serial, image(t.state)))
    }
}

pub open spec fn complete_step(s: OperationView, id: u64, saved: VoteImage,
    t: OperationView, reply: Option<VoteReply>) -> bool {
    if s.pending.is_some() && s.pending.unwrap().0 == id && s.pending.unwrap().1 == saved {
        t.state == s.state && t.serial == s.serial && t.pending.is_none()
        && reply == Some(s.pending.unwrap().3)
    } else { t == s && reply.is_none() }
}

pub open spec fn campaign_step(s: OperationView, term: u64, t: OperationView, ok: bool) -> bool {
    ok == (s.pending.is_none() && s.state.term == term && s.state.voted_for == Some(s.state.me))
    && t.serial == s.serial && t.pending == s.pending
    && t.state == state::State { role: if ok { state::Role::Candidate } else { s.state.role }, ..s.state }
}

impl WriteVote {
    pub closed spec fn number(&self) -> u64 { self.id }
    pub closed spec fn contents(&self) -> VoteImage { self.image }
    pub fn sequence(&self) -> (r: u64) ensures r == self.number(), { self.id }
    pub fn image(&self) -> (r: VoteImage) ensures r == self.contents(), { self.image }
}

impl Machine {
    pub closed spec fn view(&self) -> OperationView {
        OperationView { state: self.state, serial: self.serial,
            pending: match self.pending { None => None,
                Some(p) => Some((p.id, p.image, p.request, p.reply, p.before@)) } }
    }
    pub proof fn view_is_valid(&self)
        requires self.invariant(),
        ensures view_invariant(self.view()), self.view().state == self.state(),
    {}
    pub closed spec fn state(&self) -> State { self.state }
    pub closed spec fn idle(&self) -> bool { self.pending.is_none() }
    pub closed spec fn invariant(&self) -> bool {
        state::well_formed(self.state) && self.state.last_index == 0 && self.state.last_term == 0
        && match self.pending {
            None => true,
            Some(p) => p.id == self.serial && p.image == image(self.state)
                && state::well_formed(p.before@)
                && state::vote_step(p.before@, p.request, self.state, p.reply),
        }
    }
    pub closed spec fn pending_request(&self) -> Option<VoteRequest> {
        match self.pending { None => None, Some(p) => Some(p.request) }
    }
    pub closed spec fn pending_before(&self) -> State {
        self.pending.unwrap().before@
    }
    pub closed spec fn accepts(&self, op: &WriteVote) -> bool {
        match self.pending { None => false, Some(p) => p.id == op.id && p.image == op.image }
    }

    pub proof fn matching_operation(&self, op: &WriteVote)
        requires self.invariant(), self.accepts(op),
        ensures op.contents() == image(self.state()),
    {}

    pub fn new(me: usize, members: usize) -> (r: Option<Self>)
        ensures r.is_some() == (members > 0 && me < members),
            r.is_some() ==> r.unwrap().invariant() && r.unwrap().idle()
                && state::initial(r.unwrap().state(), me, members)
                && initial_view(r.unwrap().view(), me, members),
    {
        match State::new(me, members) {
            None => None,
            Some(s) => Some(Self { state: s, serial: 0, pending: None }),
        }
    }

    // Version and deployment identity are checked inside verified code.
    pub fn recover(me: usize, members: usize, saved: VoteImage) -> (r: Option<Self>)
        ensures r.is_some() ==> r.unwrap().invariant() && r.unwrap().idle()
            && r.unwrap().state().me == me && r.unwrap().state().members == members
            && r.unwrap().state().term == saved.term
            && r.unwrap().state().voted_for == saved.voted_for
            && image(r.unwrap().state()) == saved
            && r.unwrap().state().role == state::Role::Follower
            && r.unwrap().view().pending.is_none() && r.unwrap().view().serial == 0,
    {
        if saved.version != 1 || saved.me != me || saved.members != members { return None; }
        match State::restore_vote(me, members, saved.term, saved.voted_for) {
            None => None,
            Some(s) => Some(Self { state: s, serial: 0, pending: None }),
        }
    }

    pub fn term(&self) -> (r: u64) ensures r == self.state().term, { self.state.term }
    pub fn is_leader(&self) -> (r: bool)
        ensures r == (self.state().role == state::Role::Leader),
    { self.state.is_leader() }

    pub fn election_request(&self) -> (r: Option<state::VoteRequest>)
        ensures r.is_some() == (self.state().term < u64::MAX),
            r.is_some() ==> r.unwrap().term == self.view().state.term + 1
                && r.unwrap().candidate == self.view().state.me
                && r.unwrap().last_index == self.view().state.last_index
                && r.unwrap().last_term == self.view().state.last_term,
    { self.state.election_request() }

    pub fn campaign(&mut self, term: u64) -> (r: bool)
        requires old(self).invariant(),
        ensures self.invariant(), campaign_step(old(self).view(), term, self.view(), r),
    {
        if self.pending.is_some() { return false; }
        self.state.campaign(term)
    }

    pub fn pending_matches(&self, request: state::VoteRequest) -> (r: bool)
        ensures r == (self.pending_request() == Some(request)),
            r ==> self.view().pending.is_some() && self.view().pending.unwrap().2 == request,
    {
        match self.pending {
            None => false,
            Some(p) => p.request.term == request.term && p.request.candidate == request.candidate
                && p.request.last_index == request.last_index && p.request.last_term == request.last_term,
        }
    }

    pub fn begin_vote(&mut self, request: VoteRequest) -> (op: Option<WriteVote>)
        requires old(self).invariant(),
        ensures self.invariant(),
            op.is_some() ==> self.accepts(&op.unwrap())
                && op.unwrap().contents() == image(self.state())
                && self.pending_request() == Some(request)
                && self.pending_before() == old(self).state(),
            op.is_none() ==> self.state() == old(self).state(),
            begin_step(old(self).view(), request, self.view(),
                match op { None => None, Some(o) => Some((o.number(), o.contents())) }),
    {
        if self.pending.is_some() || self.serial == u64::MAX { return None; }
        let ghost before = self.state;
        let reply = self.state.request_vote(request);
        self.serial = self.serial + 1;
        let saved = VoteImage { version: 1, term: self.state.term,
            voted_for: self.state.voted_for, me: self.state.me, members: self.state.members };
        self.pending = Some(PendingVote { id: self.serial, image: saved,
            request, reply, before: Ghost(before) });
        Some(WriteVote { id: self.serial, image: saved })
    }

    // This is reply authorization, not a claim that arbitrary input is durable.
    // The host caller must supply this operation only after its real write returns.
    pub fn complete_vote(&mut self, completed: WriteVote) -> (reply: Option<VoteReply>)
        requires old(self).invariant(),
        ensures self.invariant(), self.state() == old(self).state(),
            reply.is_some() == old(self).accepts(&completed),
            reply.is_some() ==> self.idle()
                && state::vote_step(old(self).pending_before(),
                    old(self).pending_request().unwrap(), self.state(), reply.unwrap())
                && completed.contents() == image(self.state()),
            complete_step(old(self).view(), completed.number(), completed.contents(), self.view(), reply),
    {
        match self.pending {
            None => None,
            Some(p) => {
                let same = p.id == completed.id
                    && p.image.version == completed.image.version
                    && p.image.term == completed.image.term
                    && p.image.voted_for == completed.image.voted_for
                    && p.image.me == completed.image.me
                    && p.image.members == completed.image.members;
                if !same { return None; }
                self.pending = None;
                Some(p.reply)
            }
        }
    }
}
}

//! Per-incarnation execution journal of the real vote runtime.
//! Ghost history is updated by actual constructors and handlers; it is not a
//! replacement for cluster provenance or durable cross-crash history.
use super::{protocol as p, state, storage};
use vstd::prelude::*;
verus! {
pub enum Origin { Fresh(usize, usize), Recovered(p::VoteImage) }
pub enum Input { Request(state::VoteRequest), SelfVote(state::VoteRequest), Campaign(u64), Release(u64, p::VoteImage) }
pub enum Output { Submission(Option<(u64, p::VoteImage)>), Campaign(bool), Reply(Option<state::VoteReply>) }
pub struct History {
    pub origin: Origin,
    pub states: Seq<p::OperationView>,
    pub inputs: Seq<Input>,
    pub outputs: Seq<Output>,
}
pub open spec fn start(v: p::OperationView, origin: Origin) -> bool {
    p::view_invariant(v) && match origin {
        Origin::Fresh(me, members) => p::initial_view(v, me, members),
        Origin::Recovered(image) => p::image(v.state) == image && v.state.role == state::Role::Follower
            && v.pending.is_none() && v.serial == 0,
    }
}
pub open spec fn step(s: p::OperationView, i: Input, t: p::OperationView, o: Output) -> bool {
    match (i, o) {
        (Input::Request(q), Output::Submission(op)) => p::begin_step(s, q, t, op),
        (Input::SelfVote(q), Output::Submission(op)) =>
            q.term == s.state.term + 1 && q.candidate == s.state.me
            && q.last_index == s.state.last_index && q.last_term == s.state.last_term
            && p::begin_step(s, q, t, op),
        (Input::Campaign(term), Output::Campaign(ok)) => p::campaign_step(s, term, t, ok),
        (Input::Release(id, image), Output::Reply(reply)) => p::complete_step(s, id, image, t, reply),
        _ => false,
    }
}
pub open spec fn valid(h: History) -> bool {
    h.states.len() == h.inputs.len() + 1 && h.outputs.len() == h.inputs.len()
    && start(h.states[0], h.origin)
    && forall|k: int| 0 <= k < h.inputs.len() ==>
        step(h.states[k], #[trigger] h.inputs[k], h.states[k+1], h.outputs[k])
}
pub proof fn extend(h: History, i: Input, t: p::OperationView, o: Output) -> (next: History)
    requires valid(h), step(h.states.last(), i, t, o),
    ensures valid(next), next.states.last() == t,
        next.origin == h.origin, next.states == h.states.push(t),
        next.inputs == h.inputs.push(i), next.outputs == h.outputs.push(o),
{
    let next = History { origin: h.origin, states: h.states.push(t),
        inputs: h.inputs.push(i), outputs: h.outputs.push(o) };
    assert forall|k: int| 0 <= k < next.inputs.len() implies
        step(next.states[k], #[trigger] next.inputs[k], next.states[k+1], next.outputs[k]) by {
        if k < h.inputs.len() {
            assert(step(h.states[k], h.inputs[k], h.states[k+1], h.outputs[k]));
        } else { assert(k == h.inputs.len()); }
    }
    next
}

// The async RPC future carries this immutable caller context across storage.
// Fields are private, so the host cannot retarget a completion to a new request.
pub struct ReplyContext {
    id: u64,
    image: p::VoteImage,
    request: state::VoteRequest,
    before: Ghost<p::OperationView>,
}
impl ReplyContext {
    pub closed spec fn id(&self) -> u64 { self.id }
    pub closed spec fn image(&self) -> p::VoteImage { self.image }
    pub closed spec fn request(&self) -> state::VoteRequest { self.request }
    pub closed spec fn before(&self) -> p::OperationView { self.before@ }
}

pub struct Runtime {
    core: p::Machine,
    journal: Ghost<History>,
}
impl Runtime {
    pub closed spec fn history(&self) -> History { self.journal@ }
    pub closed spec fn view(&self) -> p::OperationView { self.core.view() }
    pub closed spec fn invariant(&self) -> bool {
        self.core.invariant() && valid(self.journal@)
        && self.journal@.states.last() == self.core.view()
    }
    pub proof fn connected(&self)
        requires self.invariant(),
        ensures valid(self.history()), self.history().states.last() == self.view(),
            p::view_invariant(self.view()),
    { self.core.view_is_valid(); }

    pub fn new(me: usize, members: usize) -> (r: Option<Self>)
        ensures r.is_some() == (members > 0 && me < members),
            r.is_some() ==> r.unwrap().invariant()
                && r.unwrap().history().inputs.len() == 0
                && r.unwrap().history().origin == Origin::Fresh(me, members),
    {
        match p::Machine::new(me, members) {
            None => None,
            Some(core) => {
                proof { core.view_is_valid(); }
                let journal = Ghost(History { origin: Origin::Fresh(me, members),
                    states: seq![core.view()], inputs: Seq::empty(), outputs: Seq::empty() });
                Some(Self { core, journal })
            }
        }
    }
    pub fn recover(me: usize, members: usize, image: p::VoteImage) -> (r: Option<Self>)
        ensures r.is_some() ==> r.unwrap().invariant()
            && r.unwrap().history().origin == Origin::Recovered(image)
            && r.unwrap().history().inputs.len() == 0,
    {
        match p::Machine::recover(me, members, image) {
            None => None,
            Some(core) => {
                proof { core.view_is_valid(); }
                let journal = Ghost(History { origin: Origin::Recovered(image),
                    states: seq![core.view()], inputs: Seq::empty(), outputs: Seq::empty() });
                Some(Self { core, journal })
            }
        }
    }
    pub fn term(&self) -> (r: u64)
        requires self.invariant(),
        ensures r == self.view().state.term,
    { proof { self.core.view_is_valid(); } self.core.term() }
    pub fn is_leader(&self) -> (r: bool)
        requires self.invariant(),
        ensures r == (self.view().state.role == state::Role::Leader),
    { proof { self.core.view_is_valid(); } self.core.is_leader() }

    pub fn begin_vote(&mut self, q: state::VoteRequest) -> (op: Option<p::WriteVote>)
        requires old(self).invariant(),
        ensures self.invariant(),
            self.history().inputs == old(self).history().inputs.push(Input::Request(q)),
            self.history().states == old(self).history().states.push(self.view()),
            self.history().outputs == old(self).history().outputs.push(Output::Submission(
                match op { None => None, Some(w) => Some((w.number(), w.contents())) })),
    {
        let op = self.core.begin_vote(q);
        let ghost output = Output::Submission(match op { None => None,
            Some(ref w) => Some((w.number(), w.contents())) });
        self.journal = Ghost(extend(self.journal@, Input::Request(q), self.core.view(), output));
        op
    }
    pub fn begin_election(&mut self) -> (r: Option<(state::VoteRequest, p::WriteVote, ReplyContext)>)
        requires old(self).invariant(),
        ensures self.invariant(),
            r.is_some() ==> r.unwrap().0.candidate == old(self).view().state.me
                && r.unwrap().0.term == old(self).view().state.term + 1
                && r.unwrap().2.request() == r.unwrap().0,
    {
        let request = match self.core.election_request() { Some(q) => q, None => return None };
        let ghost before = self.core.view();
        let op = self.core.begin_vote(request);
        let ghost output = Output::Submission(match op { None => None,
            Some(ref w) => Some((w.number(), w.contents())) });
        self.journal = Ghost(extend(self.journal@, Input::SelfVote(request), self.core.view(), output));
        match op {
            None => None,
            Some(operation) => {
                let context = ReplyContext { id: operation.sequence(), image: operation.image(),
                    request, before: Ghost(before) };
                Some((request, operation, context))
            }
        }
    }
    pub fn campaign(&mut self, term: u64) -> (r: bool)
        requires old(self).invariant(),
        ensures self.invariant(),
            r ==> self.view().state.term == term && self.view().state.role == state::Role::Candidate
                && self.view().state.voted_for == Some(self.view().state.me),
    {
        let ok = self.core.campaign(term);
        self.journal = Ghost(extend(self.journal@, Input::Campaign(term), self.core.view(), Output::Campaign(ok)));
        ok
    }

    pub fn begin_rpc(&mut self, request: state::VoteRequest)
        -> (r: Option<(p::WriteVote, ReplyContext)>)
        requires old(self).invariant(),
        ensures self.invariant(),
            r.is_some() ==> r.unwrap().1.id() == r.unwrap().0.number()
                && r.unwrap().1.image() == r.unwrap().0.contents()
                && r.unwrap().1.request() == request
                && r.unwrap().1.before() == old(self).view(),
            self.history().inputs == old(self).history().inputs.push(Input::Request(request)),
    {
        let ghost before = self.core.view();
        match self.begin_vote(request) {
            None => None,
            Some(operation) => {
                let context = ReplyContext { id: operation.sequence(), image: operation.image(),
                    request, before: Ghost(before) };
                Some((operation, context))
            }
        }
    }

    pub fn finish_rpc(&mut self, context: ReplyContext, written: storage::WrittenVote)
        -> (r: Option<state::VoteReply>)
        requires old(self).invariant(),
        ensures self.invariant(),
            r.is_some() ==> written.id() == context.id() && written.image() == context.image()
                && p::image(self.view().state) == context.image()
                && (r.unwrap().granted ==> r.unwrap().term == context.request().term
                    && self.view().state.voted_for == Some(context.request().candidate)),
            r.is_none() && (written.id() != context.id() || written.image() != context.image())
                ==> self.history() == old(self).history(),
    {
        if !written.matches(context.id, context.image) { return None; }
        if !self.core.pending_matches(context.request) { return None; }
